/**
 * Typed, validated access to the site's data files.
 *
 * - release-facts.json is GENERATED by `python scripts/site_facts.py` from pyproject.toml, the package
 *   version, the latest release tag and docs/engineering/evidence-matrix.json. Never edit it by hand;
 *   `python scripts/site_facts.py --check` (also run by the test suite) fails when it is stale.
 * - providers.json is edited by hand (and validated by the same script).
 *
 * The build fails here if either file carries an unknown status or label, so a typo cannot render.
 */
import releaseFacts from './release-facts.json';
import providerData from './providers.json';

export const EVIDENCE_STATUSES = [
  'DEMONSTRATED',
  'EXPERIMENTAL',
  'NEGATIVE_RESULT',
  'INCONCLUSIVE',
  'NOT_YET_DEMONSTRATED',
  'BLOCKED',
  'UNSUPPORTED',
] as const;
export type EvidenceStatus = (typeof EVIDENCE_STATUSES)[number];

export const PROVIDER_LABELS = ['EXECUTION', 'HOST_ONLY', 'CONTEXT_SKILLS_ONLY', 'PLANNED', 'BLOCKED', 'UNSUPPORTED'] as const;
export type ProviderLabel = (typeof PROVIDER_LABELS)[number];

/** Visual tone per status. The label text is always shown too: colour never carries meaning alone. */
export type Tone = 'pass' | 'fail' | 'pre' | 'abstain' | 'unknown';
export const statusTone: Record<EvidenceStatus, { tone: Tone; dashed?: boolean }> = {
  DEMONSTRATED: { tone: 'pass' },
  EXPERIMENTAL: { tone: 'abstain' },
  NEGATIVE_RESULT: { tone: 'fail' },
  INCONCLUSIVE: { tone: 'pre' },
  NOT_YET_DEMONSTRATED: { tone: 'unknown' },
  BLOCKED: { tone: 'fail', dashed: true },
  UNSUPPORTED: { tone: 'unknown', dashed: true },
};
export const labelTone: Record<ProviderLabel, { tone: Tone; dashed?: boolean }> = {
  EXECUTION: { tone: 'pass' },
  HOST_ONLY: { tone: 'abstain' },
  CONTEXT_SKILLS_ONLY: { tone: 'abstain', dashed: true },
  PLANNED: { tone: 'unknown', dashed: true },
  BLOCKED: { tone: 'fail', dashed: true },
  UNSUPPORTED: { tone: 'unknown', dashed: true },
};

export interface EvidenceEntry {
  id: string;
  title: string;
  status: EvidenceStatus;
  stat: string;
  result: string;
  date: string;
  date_note?: string;
  sample_size: string;
  method: string;
  limits?: string;
  source: string;
  source_url: string | null;
  featured?: boolean;
}

export interface Provider {
  id: string;
  name: string;
  agent: string;
  label: ProviderLabel;
  execution: {
    status: ProviderLabel;
    observed: string;
    verified_on: string;
    version: string;
    sample: string;
    platforms: string;
    source: string;
  };
  host: string;
  cost: string;
}

function fail(msg: string): never {
  throw new Error(`site data: ${msg}. Fix the input and run \`python scripts/site_facts.py\`.`);
}

if (releaseFacts.schema !== 'repo-ai.site-release-facts/1') fail('release-facts.json has an unexpected schema');
if (providerData.schema !== 'repo-ai.providers/1') fail('providers.json has an unexpected schema');

export const facts = releaseFacts;

export const evidenceStatuses = releaseFacts.evidence.statuses as Record<EvidenceStatus, string>;
export const evidence: EvidenceEntry[] = releaseFacts.evidence.entries.map((e) => {
  if (!(EVIDENCE_STATUSES as readonly string[]).includes(e.status)) fail(`unknown evidence status ${e.status} (${e.id})`);
  for (const k of ['title', 'result', 'date', 'sample_size', 'method', 'source'] as const) {
    if (!e[k]) fail(`evidence entry ${e.id} has no ${k}`);
  }
  return e as EvidenceEntry;
});
for (const s of EVIDENCE_STATUSES) if (!evidenceStatuses[s]) fail(`status ${s} has no definition`);

export const providerLabels = providerData.labels as Record<ProviderLabel, string>;
export const providersAsOf = providerData.as_of;
export const providers: Provider[] = providerData.providers.map((p) => {
  if (!(PROVIDER_LABELS as readonly string[]).includes(p.label)) fail(`unknown provider label ${p.label} (${p.id})`);
  if (!(PROVIDER_LABELS as readonly string[]).includes(p.execution.status)) fail(`unknown execution status (${p.id})`);
  return p as Provider;
});

export const repoBlob = (path: string) => `${releaseFacts.repository.url}/blob/main/${path}`;

/** Group entries by status, in display order, dropping empty groups. */
export function byStatus(entries: EvidenceEntry[]) {
  return EVIDENCE_STATUSES.map((status) => ({ status, items: entries.filter((e) => e.status === status) })).filter(
    (g) => g.items.length > 0,
  );
}

export const humanStatus = (s: string) => s.replace(/_/g, ' ');
